WITH breast_cancer_persons AS (SELECT DISTINCT co.person_id FROM condition_occurrence co WHERE co.condition_concept_id IN (SELECT descendant_concept_id FROM concept_ancestor WHERE ancestor_concept_id IN (4112853))), mastectomy_persons AS (SELECT DISTINCT po.person_id FROM procedure_occurrence po WHERE po.procedure_concept_id IN (SELECT descendant_concept_id FROM concept_ancestor WHERE ancestor_concept_id IN (4066543))) SELECT b.person_id FROM breast_cancer_persons b WHERE NOT EXISTS (SELECT 1 FROM mastectomy_persons m WHERE m.person_id = b.person_id);